const save = async (event: FormEvent) => {
    event.preventDefault()
    if (!form || !initial || !details) return
    let sharedDirectories: string[]
    try {
      sharedDirectories = parseSharedDirectoriesText(form.sharedDirectories)
    } catch (error) {
      context.toast('Invalid shared directories', messageOf(error))
      return
    }
    const patch = changes(initial, form)
    if (!isSafeIcon(form.icon)) {
      context.toast('Invalid project icon', 'Use a plain-text emoji or symbol; URLs, SVG and HTML are not allowed.')
      return
    }
    const identityChanged = form.icon !== initial.icon || form.color !== initial.color || form.trackerProject !== initial.trackerProject ||
      form.externalVisibility !== initial.externalVisibility
    const sharedDirectoriesChanged = JSON.stringify(sharedDirectories) !== JSON.stringify(parseSharedDirectoriesText(initial.sharedDirectories))
    if (Object.keys(patch).length === 0 && !identityChanged && !sharedDirectoriesChanged) return onClose()
    setBusy(true)
    try {
      if (Object.keys(patch).length > 0) await context.call('quirky.repo/set', { repo: repo.id, ...patch })
      if (identityChanged || sharedDirectoriesChanged) await context.call('quirky.worktree/setProjectMetadata', {
        repo: repo.id,
        ...(identityChanged ? {
          identity: {
            icon: form.icon.trim() || null,
            color: form.color.trim() || null,
            trackerProject: form.trackerProject.trim() || null
          },
          externalVisibility: form.externalVisibility
        } : {}),
        ...(sharedDirectoriesChanged ? { sharedDirectories } : {})
      })
      onClose()
    } catch (error) {
      context.toast('Could not save project settings', messageOf(error))
      setBusy(false)
    }
  }

const browseLocation = async () => {
    if (!form) return
    try {
      const selected = await pickNativeFolder(context, 'Choose worktree location', form.worktreeLocation.trim() || repo.path)
      if (selected !== null) set('worktreeLocation', selected)
    } catch (error) {
      context.toast(
        error instanceof FolderPickerUnavailableError ? 'Native folder picker unavailable' : 'Could not choose worktree location',
        messageOf(error)
      )
    }
  }

export async function pickNativeFolder(context: UiPluginContext, title: string, startingFolder?: string): Promise<string | null> {
  let result: unknown
  try {
    const request: FolderPickerRequest & { multiple: false } = {
      title,
      ...(startingFolder ? { startingFolder } : {}),
      multiple: false
    }
    result = await context.call('desktop.folder.pick', request as Record<string, unknown>)
  } catch (error) {
    const code = (error as { code?: unknown } | null)?.code
    const reason = (error as { data?: { reason?: unknown } } | null)?.data?.reason
    const unavailableConflict = code === RpcErrorCode.Conflict && typeof reason === 'string' &&
      reason.toLowerCase().includes('folder') && reason.toLowerCase().includes('picker') && reason.toLowerCase().includes('unavailable')
    if (code === RpcErrorCode.MethodNotFound || unavailableConflict) throw new FolderPickerUnavailableError()
    throw error
  }
  if (typeof result !== 'object' || result === null || Array.isArray(result)) {
    throw new Error('desktop.folder.pick returned an invalid result.')
  }
  const picked = result as Partial<FolderPickerResult>
  if (typeof picked.cancelled !== 'boolean' || !Array.isArray(picked.paths) || !picked.paths.every((path) => typeof path === 'string')) {
    throw new Error('desktop.folder.pick returned an invalid result.')
  }
  if (picked.cancelled) return null
  if (picked.paths.length !== 1 || picked.paths[0] === '') {
    throw new Error('desktop.folder.pick must return exactly one folder when not cancelled.')
  }
  return picked.paths[0] as string
}

export async function importFolder(context: UiPluginContext, path: string, group?: string): Promise<boolean> {
  try {
    const result = (await context.call('quirky.repo/import', { path, ...(group ? { group } : {}) })) as {
      failed: number
      results: { path: string; status: string; error?: string }[]
    }
    if (result.failed > 0) {
      const first = result.results.find((r) => r.status === 'failed')
      context.toast('Some repositories could not be added', first?.error ? `${first.path}: ${first.error}` : `${result.failed} failed`)
    }
    return true
  } catch (error) {
    context.toast('Could not add project', messageOf(error))
    return false
  }
}

